  str_files_story_title_5301 = "幸福的金子·一",
  str_files_story_title_5303 = "幸福的金子·二",
  str_files_story_title_5305 = "幸福的金子·三",
  str_files_story_des_101 = "只剩娜席里絲一個人還沒填「基本資料表」了，不知為何，她十分抗拒這件事……？",
  str_files_story_des_103 = "意外遇到了兩位「娜席里絲」，難道其中一位便是她口中的「姐姐」？！完全分不出來……",
  str_files_story_des_105 = "劇情5",
  str_files_story_des_107 = "劇情7",
  str_files_story_des_110 = "劇情10",
  str_files_story_des_201 = "最近總覺得有芒刺在背的「目光」尾隨，為了引出「那個人」，你搞了一齣拙劣的表演……",
  str_files_story_des_203 = "長官出乎意料地隨和，但強大的氣場還是讓你手足無措——有個問題，不知道該不該問……",
  str_files_story_des_205 = "劇情5",
  str_files_story_des_207 = "劇情7",
  str_files_story_des_209 = "劇情9",
  str_files_story_des_210 = "劇情10",
  str_files_story_des_402 = "劇情2",
  str_files_story_des_404 = "劇情4",
  str_files_story_des_406 = "劇情6",
  str_files_story_des_408 = "劇情8",
  str_files_story_des_501 = "劇情1",
  str_files_story_des_503 = "劇情3",
  str_files_story_des_505 = "劇情5",
  str_files_story_des_507 = "劇情7",
  str_files_story_des_509 = "劇情9",
  str_files_story_des_510 = "劇情10",
  str_files_story_des_602 = "與城主大人的女兒打交道沒那麼簡單，你企圖展現出自己的領袖特質，然而……",
  str_files_story_des_604 = "卡蓮似乎對自己的立場感到很矛盾。不擅長「閱讀空氣」的你，該怎麼讓她敞開心扉呢……",
  str_files_story_des_606 = "劇情6",
  str_files_story_des_608 = "劇情8",
  str_files_story_des_609 = "劇情9",
  str_files_story_des_610 = "劇情10",
  str_files_story_des_802 = "劇情2",
  str_files_story_des_804 = "劇情4",
  str_files_story_des_806 = "劇情6",
  str_files_story_des_901 = "劇情1",
  str_files_story_des_903 = "劇情3",
  str_files_story_des_905 = "劇情5",
  str_files_story_des_907 = "劇情7",
  str_files_story_des_910 = "劇情10",
  str_files_story_des_1002 = "劇情2",
  str_files_story_des_1004 = "劇情4",
  str_files_story_des_1006 = "劇情6",
  str_files_story_des_1008 = "劇情8",
  str_files_story_des_1009 = "劇情9",
  str_files_story_des_1102 = "雖然不是定期檢裝日，壓力卻排山倒海而來——啟光軍團長之一的希羅娜，即將插手巨像管理？！希望一切順利……",
  str_files_story_des_1104 = "極度關心巨像和你的希羅娜似乎有著「自己的理由」？也許她從你身上，看到了某些自己的期望……",
  str_files_story_des_1106 = "劇情5",
  str_files_story_des_1108 = "劇情7",
  str_files_story_des_1110 = "劇情10",
  str_files_story_des_1201 = "因為一件「小事」，巨像中傳來超大的爭吵聲！看來無論你願不願意，都要去當一回「和事佬」了……",
  str_files_story_des_1203 = "涅墨西斯似乎對「公平與正義」有著非常強烈的執著。也許應該多抽點時間跟她聊聊，瞭解她不為人知的一面……",
  str_files_story_des_1205 = "劇情5",
  str_files_story_des_1207 = "劇情7",
  str_files_story_des_1210 = "劇情10",
  str_files_story_des_1302 = "劇情2",
  str_files_story_des_1304 = "劇情4",
  str_files_story_des_1306 = "劇情6",
  str_files_story_des_1308 = "劇情8",
  str_files_story_des_1309 = "劇情9",
  str_files_story_des_1310 = "劇情10",
  str_files_story_des_1402 = "城主大人親自視察巨像？！手忙腳亂的你一開始就遲到，接下來千萬別出更多差錯了——盡量啦！",
  str_files_story_des_1404 = "「和藹可親」的城主大人，再次氣勢十足地來到你面前——這究竟是怎麼回事？！身為巨像負責人，你再次感受到「期待」與「失望」並存的目光……",
  str_files_story_des_1406 = "劇情6",
  str_files_story_des_1408 = "劇情8",
  str_files_story_des_1409 = "劇情9",
  str_files_story_des_1410 = "劇情10",
  str_files_story_des_1701 = "劇情1",
  str_files_story_des_1703 = "劇情3",
  str_files_story_des_1705 = "劇情5",
  str_files_story_des_1707 = "劇情7",
  str_files_story_des_1802 = "一張現場音樂會的邀請函？你正猶豫著要不要放棄休息時間參與這場奇怪的活動時，一陣猛烈的敲門聲傳來……",
  str_files_story_des_1804 = "約定的日子到了，不知道蕾吉娜的現場音樂會是什麼樣子？你隱約感到一絲不安……",
  str_files_story_des_1806 = "劇情6",
  str_files_story_des_1808 = "劇情8",
  str_files_story_des_1809 = "劇情9",
  str_files_story_des_1810 = "劇情10",
  str_files_story_des_1901 = "劇情1",
  str_files_story_des_1903 = "劇情3",
  str_files_story_des_1905 = "劇情5",
  str_files_story_des_1907 = "劇情7",
  str_files_story_des_1910 = "劇情10",
  str_files_story_des_2101 = "劇情1",
  str_files_story_des_2103 = "劇情3",
  str_files_story_des_2105 = "劇情5",
  str_files_story_des_2107 = "劇情7",
  str_files_story_des_2201 = "劇情1",
  str_files_story_des_2203 = "劇情3",
  str_files_story_des_2205 = "劇情5",
  str_files_story_des_2301 = "劇情3",
  str_files_story_des_2303 = "劇情5",
  str_files_story_des_2305 = "劇情7",
  str_files_story_des_2307 = "劇情9",
  str_files_story_des_2310 = "劇情10",
  str_files_story_des_2501 = "又是尋常的一天，又收到了好幾封針對卡戎的「投訴信」……看來必須找他談談了……",
  str_files_story_des_2503 = "完全沒辦法跟卡戎正常溝通的樣子呢……找機會多蒐集一點情報吧，也許能搞清楚他那股「狂熱」的根源……",
  str_files_story_des_2505 = "劇情5",
  str_files_story_des_2507 = "劇情7",
  str_files_story_des_2509 = "劇情9",
  str_files_story_des_2510 = "劇情10",
  str_files_story_des_2602 = "劇情2",
  str_files_story_des_2604 = "劇情4",
  str_files_story_des_2606 = "劇情6",
  str_files_story_des_2608 = "劇情8",
  str_files_story_des_2609 = "劇情9",
  str_files_story_des_2610 = "劇情10",
  str_files_story_des_2801 = "你總是有一股不好的預感……到底是什麼呢？啊，遠處那位是拉斐爾？她為什麼在瘋狂……招手？",
  str_files_story_des_2803 = "拉斐爾對改進醫療手段的狂熱真是……令人頭痛。只希望今天不要再被她「算計」了，不然就連你也想寫投訴信了……",
  str_files_story_des_2805 = "劇情5",
  str_files_story_des_2807 = "劇情7",
  str_files_story_des_2809 = "劇情9",
  str_files_story_des_2810 = "劇情10",
  str_files_story_des_2902 = "劇情2",
  str_files_story_des_2904 = "劇情4",
  str_files_story_des_2906 = "劇情6",
  str_files_story_des_2908 = "劇情8",
  str_files_story_des_2909 = "劇情9",
  str_files_story_des_2910 = "劇情10",
  str_files_story_des_3202 = "劇情2",
  str_files_story_des_3204 = "劇情4",
  str_files_story_des_3206 = "劇情6",
  str_files_story_des_3301 = "問個問題：你對自己朝夕相處的這位「老朋友」究竟認識多深？是否瞭解她的真實想法？也許，答案還在很深的地方呢……",
  str_files_story_des_3303 = "和薇絲約好進行某種「問答調查」，感覺比較類似考核？你懷著忐忑的心情赴約了，希望不論是什麼考驗，薇絲能稍微放你一馬……",
  str_files_story_des_3305 = "劇情6",
  str_files_story_des_3307 = "劇情8",
  str_files_story_des_3310 = "劇情10",
  str_files_story_des_3501 = "最近阿褐送貨越來越常遲到了呢，不知道是什麼原因？找她聊聊吧……",
  str_files_story_des_3503 = "原來阿褐是路痴嗎……做這一行還真不容易呢。所以抄寫地圖真的會對記路有幫助嗎……",
  str_files_story_des_3505 = "劇情5",
  str_files_story_des_3602 = "劇情1",
  str_files_story_des_3604 = "劇情3",
  str_files_story_des_3606 = "劇情5",
  str_files_story_des_3608 = "劇情7",
  str_files_story_des_3610 = "劇情10",
  str_files_story_des_3802 = "貢露小姐最近對巨像保養非常用心，似乎抱有極大的熱情。今天是你們第一次正式見面，不知道她的個性怎麼樣呢？",
  str_files_story_des_3804 = "貢露小姐似乎非常喜歡玩遊戲呢……希望這一點不會影響到她的日常工作，不然就麻煩了……",
  str_files_story_des_3806 = "劇情6",
  str_files_story_des_3808 = "劇情8",
  str_files_story_des_3809 = "劇情9",
  str_files_story_des_3810 = "劇情10",
  str_files_story_des_4001 = "劇情1",
  str_files_story_des_4003 = "劇情3",
  str_files_story_des_4005 = "劇情5",
  str_files_story_des_4007 = "劇情7",
  str_files_story_des_4101 = "每逢大型集會，Miss.白蘭都會格外忙碌。要不要去看看呢？如果能幫上忙就更好了。希望不會幫倒忙……",
  str_files_story_des_4103 = "好像真的幫了倒忙，Miss.白蘭現在更忙了……也許有機會稍微彌補一下吧？",
