  str_files_story_des_4701 = "最近卓婭的行蹤有點可疑呢——飄忽不定、時隱時現，感覺似乎在……觀察些什麼？",
  str_files_story_des_4703 = "原來卓婭對緋長官還抱著「另類」的依賴嗎……真想瞭解一下她的故事呢，只是不知道卓婭願不願意分享？",
  str_files_story_des_4705 = "劇情5",
  str_files_story_des_4801 = "身為巨像負責人，在日常工作之餘「蒐集情報」也是任務之一，這次似乎要利用與烈雀同行的機會？",
