  str_files_story_title_30132 = "再一次呼喚",
  str_files_story_title_35042 = "工作的意義",
  str_files_story_title_30133 = "後日談：樂園已達",
  str_files_story_des_10101 = "【待新增】",
  str_files_story_des_10201 = "接連戰鬥讓眾人無法休息，大家都快撐不住了。最大的敵人或許不是暗鬼，而是疲勞……",
  str_files_story_des_10202 = "由於安潔兒的請求，你才能發現巨像上另一間房間真正的用途，也發現了安潔兒的另一面……",
  str_files_story_des_10203 = "「可憐」的多孚似乎沒辦法好好休息，幫她想想辦法吧？雖然她很懶，但是畢竟還在工作……她自己是這麼說的。",
  str_files_story_des_10204 = "面對伶牙俐齒的卓婭，你只好答應她的要求。雖然卓婭對最終結果不甚理想，卻也讓她達到了自己的目的……",
  str_files_story_des_10301 = "在臨空者號被送往28號地下城的期間，卡戎向你介紹了28號地下城與啟光聯邦的一些事，這是你瞭解這個世界的好機會。",
  str_files_story_des_10302 = "孟德爾頌事件結束後，你與緋正在臨空者號內閒晃。或許是對空裔感到好奇，緋久違地向你訴說了一些平常不會輕易說出口的話。",
  str_files_story_des_10303 = "難得有空，薇絲居然在測量巨像的種種參數，難道她對巨像打起了什麼主意？不會吧……",
  str_files_story_des_10304 = "卡蓮、薇絲聊起了在白夜城的日子，並針對白夜城的統治秩序，進行了一場「友善」的討論……",
  str_files_story_des_10305 = "才離開一下，迦南城的日常事務就陷入了混亂，眾人手足無措。聽聞此事的薇薇安連忙趕去解決，而你也見到了她那堪稱「恐怖」的能力……",
  str_files_story_des_10306 = "神祕人修好了巨像的破損之處，她的目的是什麼？只是一場遊戲嗎？還是說，這是啟光聯邦最新的裝備測試！？",
  str_files_story_des_10307 = "在吞噬者號上有過一面之緣的神祕人「浮士德」，再次出現在巨像上，並親自帶來了關於自己的「背景調查報告」……？",
  str_files_story_des_10308 = "前往空谷前，你和薇絲決定去探望住院的薇薇安。可是半路上，薇絲的錢包忽然不見了……難道是被人偷走了？",
  str_files_story_des_20100 = "【待新增】",
  str_files_story_des_20101 = "貢露突然要你和她一起進行巨像整備，並要求你跟她進行一場對決遊戲，如果你敗給她，她就要對巨像做一些「多餘」的事情……",
  str_files_story_des_20200 = "緋邀請你去遊覽迦南城，她送給你一張奇怪的紙條，並聊起了啟光將軍和「紙條」的故事。",
  str_files_story_des_20201 = "某次啟光會議後，巴頓突然找你說明情況，這一切的原因竟是巴頓擔心你會被其他三位將軍給「吃了」？",
  str_files_story_des_20202 = "你原本只是詢問「戰鬥」對於巴頓的意義，沒想到卻被對方強行開始一場象棋遊戲。在巴頓無厘頭地宣布勝利後，他表示「勝利」才是「戰鬥」的意義。",
  str_files_story_des_20203 = "你出現了睡眠問題，希羅娜打算用自己擅長的方式幫你解決問題。這位長官提出的解決方案雖然有些粗暴，但簡單有效，一勞永逸。",
  str_files_story_des_20204 = "你回到自己的房間，發現有人留下了神祕紙條，你運用感應能力，發現一切似乎與緋長官有關。就在你與緋的對質過程中，真相漸漸浮出水面。",
  str_files_story_des_20205 = "巨像中，雷霆似乎正在為什麼而煩惱。你接近後，氣氛似乎愈發詭譎，一場「追逐」開始在黑暗中悄悄展開。",
  str_files_story_des_20300 = "你會沉溺於虛幻的喜樂？還是滿足於真實的痛苦？「舊夢」張開雙臂，由此可窺見真理結社一隅。",
  str_files_story_des_20301 = "如果你「無論如何都想知道明天是什麼樣子」，維多利亞當然會尊重你的選擇……",
  str_files_story_des_20302 = "照顧浮士德的白箱並不容易，更別說它的個性像隻貓一樣陰晴不定。",
  str_files_story_des_20303 = "真正的美食之王能夠吞噬一切，無論是超大量的肉、藤曼還是沙子、泥土，但唯有胡蘿蔔……",
  str_files_story_des_20304 = "聖釘靜靜地站在巨像上，看起來蒼白又單薄。她的目光如此平靜，彷彿不會被任何東西動搖，然而這或許只是表象……",
  str_files_story_des_20400 = "你心血來潮，決定前往咖啡廳品嚐克娜莉的手藝，途中卻遇到了大打出手的莉奧娜與修拉德。兩位的肢體衝突似乎在巨像內早已是家常便飯，為瞭解決紛爭，你只好向克娜莉求助。",
  str_files_story_des_20401 = "由於你在睡夢中聽到「奇怪的聲音」而睡眠不足，精神緊繃。克娜莉聽說這件事後，表示想提供協助，她以自己的經驗對此事做出了判斷，直到「奇怪的聲音」的本體現身……",
  str_files_story_des_20402 = "修拉德看見你出現十分意外。得知你並不在白夜城後，他對克萊肯的態度愈發惡劣。你發現修拉德和克萊肯的關係似乎並不好，你詢問後，修拉德講起了一段往事……",
  str_files_story_des_20403 = "你發現「影狼」半夜偷偷進入了你的房間。你去找修拉德對質，並要求他管好「影狼」，對方表示卻「做不到」？",
  str_files_story_des_20404 = "身為見證人，珍默默地見證著一切；殊不知她身邊的人也見證著她冷漠的外表下，那顆溫柔的心。",
  str_files_story_des_20405 = "莉奧娜平常都和她的小龍桑咚形影不離。但最近，桑咚好像不會纏著莉奧娜了；與此同時，和桑咚一起消失了的還有……",
  str_files_story_des_20500 = "「激鬥應援」演唱會！搖滾、激情、熱血開唱！現場觀眾火熱募集中！請盡速聯繫狡木報名——",
  str_files_story_des_20501 = "為了徹底碾碎不自量力的芭芭拉，蕾吉娜的歌曲必須完美且震撼人心！！",
  str_files_story_des_20502 = "小不點的最新發明有：「蕾吉娜極限死亡搖滾鬧鐘」、「超級燒飯火箭筒」，以及「特酷聚光燈」。",
  str_files_story_des_20503 = "歐緹的行程表大爆滿，巨大的壓力幾乎壓垮她，再這樣下去，她一定會……",
  str_files_story_des_20504 = "美麗的霞光在透明瓶中閃爍，如同小小的夢，芭芭拉很喜歡，而她也會給你最好的回禮。",
  str_files_story_des_20506 = "「天下沒有白吃的午餐」，正如狡木的神祕大禮雖然看起來便宜又實惠，但其實早就標好了價格。",
  str_files_story_des_20600 = "【待新增】",
  str_files_story_des_20601 = "曾經在北境王宮獨自生活的露易絲，某天遇到了四處旅行的諾爾。這一次，是關於她們相識的故事。",
  str_files_story_des_20602 = "露易絲講了新的童話故事給失眠的你聽，還貼心地帶了手工布丁來。可是眼前香噴噴的布丁，似乎有什麼地方不太對勁……",
  str_files_story_des_20603 = "伯利恆請你去監督露易絲與諾爾的學習情況，誰知道你卻不小心「引火上身」……",
  str_files_story_des_20604 = "你問娜席里絲能不能提供一些鮮花，好讓你放鬆一下最近緊繃的神經。如你所願娜席里絲幫你準備了大量鮮花，只是數量上似乎有點誤會……？",
  str_files_story_des_20605 = "想研究光靈能力的你，向號稱「什麼都知道」的諾爾諮詢。諾爾雖然用自己的能力提供了一組「完美」的數據，然而結果似乎不怎麼「完美」……",
  str_files_story_des_20606 = "原本只是來幫你打掃房間的諾爾突然潔癖發作，為了一小塊污漬反覆擦了一面牆老半天。你決定乾脆親自試試。",
  str_files_story_des_20607 = "奧斐娜為了能和巨像中的其他人更加友好和睦地相處，決定先鍛鍊一下自己對於「被他人觸摸自己的角」這種排斥的感覺，為此她找到了導航員作為練習對象。",
  str_files_story_des_20700 = "【待新增】",
  str_files_story_des_20701 = "你正在尋找傳聞中的「閃光跳跳人」，又遇見了爭執中的比比比約恩與菈比，她們拉著你要你進行奇怪的評論。你很快便發現，原來你要找的「閃光跳跳人」就是……",
  str_files_story_des_20702 = "瑪姬處找著什麼東西，很著急的樣子。但一向害羞的她，一聽到要找很多地方才有可能找到失物時，竟然……？",
  str_files_story_des_20800 = "【待新增】",
  str_files_story_des_20801 = "艾米想當個稱職的審判騎士巡邏巨像，並幫助大家解決煩惱。她十分努力，卻似乎成效不彰，於是她邀請了你……",
  str_files_story_des_20802 = "巨像上疑似發生了大事件！白夜城的審判長大人居然親自出動調查，究竟發生了什麼事呢……",
  str_files_story_des_20803 = "米潔妮又在審判著什麼，但這次的審判價格……似乎太離奇了一點？",
  str_files_story_des_20900 = "【待新增】",
  str_files_story_des_20901 = "拉斐爾發現了巨像的祕密？她還要嘗試治療巨像？原來，拉斐爾之前曾經治癒過與巨像類似的同伴……",
  str_files_story_des_20902 = "雖然能掌握火焰，但是烏列爾常常陷入悲觀。你能為她帶來溫暖嗎？",
  str_files_story_des_20903 = "「慢就是穩，穩就能快。」加百列的話語讓你困惑。不過，有時候休息一下也不錯。",
  str_files_story_des_20904 = "偶然的機會下，你將黎明變晶石送給了米迦勒，少女平靜如水的內心似乎出現了一絲波瀾。",
  str_files_story_des_21000 = "巨像上突然開始了一場奇妙的詩歌評選活動，被選為評審的你，更喜歡誰的詩歌呢？",
  str_files_story_des_21001 = "你詢問基汀唱詩班四人組「他們究竟誰是男孩，誰是女孩？」然而四人表示，你必須通過他們的考驗，才會告訴你答案。",
  str_files_story_des_21002 = "基汀趁著舒瓦茲休息時，將花朵插在他的耳朵上。舒瓦茲對此事惱怒不已，並要求你來主持公道。於是在你們的共同努力下，一份特別的「事件記錄」產生了……",
  str_files_story_des_21003 = "你主動與基汀唱詩班溝通，表示「希望他們能改變自己的說話方式」。在你的一番努力下，幾個孩子終於感受到了你的用心良苦，並拒絕了。",
  str_files_story_des_21004 = "深夜時分傳來的悠揚旋律，但不知何故伴隨著幽怨的哭聲，並在高潮處戛然而止。",
  str_files_story_des_21005 = "巨像角落有人「種」了奇怪的「白花」，你調查後發現，似乎是尤萊雅做的。不過……這又是為什麼？",
  str_files_story_des_21100 = "伊斯塔萬幫寄來了三封信，並要求你帶上其中一封與他們見面。將調查到的所有資訊記錄下來之後，你做出了最終選擇……",
  str_files_story_des_21101 = "克萊肯用拐彎抹角的方式邀請你玩「預言遊戲」，直到最後你才發現他真正的目的竟然是……",
  str_files_story_des_21102 = "克萊肯在收到禮物「迪伯里冒險圖」後，邀請你一起來玩，順便還說了「他與冒險圖」的奇妙故事……",
  str_files_story_des_21104 = "喝下這杯酒吧！謊言的味道甜蜜又溫柔，「忠心與誠實」的滋味卻是如此苦澀。",
  str_files_story_des_21105 = "咖啡廳被翻得一團亂，櫃子裡的食物都不翼而飛了，然而發來消息的塞留古就是最先到達現場的人，也是最具嫌疑的人……",
  str_files_story_des_21106 = "回憶起與帕蒂帕西一起玩捉迷藏的那段經歷，她們唱的那首歌真是奇怪又詭異，但也有聽到之後令人安心的時刻。",
  str_files_story_des_21200 = "法庭？審判？啟光聯邦的支援本部當中出現了罪犯？真相究竟是什麼？",
  str_files_story_des_21201 = "薇薇安總是那麼忙碌，即便在巨像上也一樣。然而，當她接到一杯慰勞飲品時，卻出現了奇怪的反應……",
  str_files_story_des_21202 = "為了感謝你的慷慨，薇薇安為你準備了一份「大禮」，面對她的盛情，你吃得消嗎？",
  str_files_story_des_21204 = "平常總是一副「華麗姿態」的卡戎，最近突然變得神祕兮兮的。他似乎對螢盞產生了興趣，這又是為什麼呢？",
  str_files_story_des_21205 = "偶然遇到薇絲，卻發現她正在進行一項困難的計劃，你能幫她完成嗎？",
  str_files_story_des_21206 = "啟光聯邦的監察長，突然有事相求？而委託的內容只是代送一套禮物？真的只是這樣嗎？",
  str_files_story_des_21207 = "無論是菲莉詩還是尤彌，起司都是她們共同的死穴，遇到就會發狂。起司到底對她們做了什麼？",
  str_files_story_des_21300 = "每個禮拜，舒瓦茲都會「消失」一小時，他到底是做什麼去了？",
  str_files_story_des_21301 = "娜汀突然表示想為你做些什麼，她的努力和貼心讓你十分感動，直到她向你道歉，你才知道這一切竟然是因為……",
  str_files_story_des_21302 = "你好奇白蘭小姐「引路人」的身分，沒想到卻反而激起了白蘭小姐對「導航員」的好奇，於是一場奇妙的比較開始了。",
  str_files_story_des_21303 = "卡蓮在撿到「螢盞攜行者」後，對這個養育你的「母親」產生了濃厚的興趣，也終於願意在最後提起你所感應到的，關於她母親的記憶……",
  str_files_story_des_21304 = "你在巨像裡悠哉閒晃，路過舒瓦茲身邊時，卻被叫住了……",
  str_files_story_des_21400 = "「沙漠的盡頭」究竟在哪裡，亡命陣列又將何去何從？",
  str_files_story_des_21401 = "傳說中的「天災惡魔」無惡不作，所到之處如天災過境，毀天滅地，她的項上人頭懸賞金額高達五億。",
  str_files_story_des_21402 = "焦慮的卡夫卡、茫然的導航員，這一切都是因為法蘭茲失蹤了。偌大的巨像上，那頭「忠誠的小黑狗」到底跑哪去了？",
  str_files_story_des_21403 = "大就是好、高就是強、重就是有力量，即使只有一公斤的差距也是不能忍受的重大失敗。為了洗刷恥辱，索克再次向庫瑪提出挑戰……",
  str_files_story_des_21404 = "購買了一大堆假冒劣質假貨的黑潮試圖找狡木理論，然而不知不覺之間卻又被狡木連哄帶騙買了奇怪的新產品。這次連導航員都救不了他……",
  str_files_story_des_21500 = "彌加德發現巨像上有「高級暗鬼」潛入，便將目標關在咖啡廳裡。你們為了從暗鬼口中問出重要的情報，找來了幾位「審問大師」，最後得知……",
  str_files_story_des_21501 = "針對孰強孰弱的問題，紅與黑對你展開了一場「友好」的「詢問」。面對二位的質問，你最終表達出了心中所想：何苦要分出高下，搭檔的意義不就在於截長補短嗎？",
  str_files_story_des_21502 = "面對越來越多的投訴，你不得不與彌加德好好聊一聊了——關於她令人「不適」的行為作風問題！但到最後，似乎變成了你替大家抗下所有……？",
  str_files_story_des_21503 = "艾希的房間裡，總會傳出神祕的叫聲，為了一探究竟你鼓起勇氣開口發問，於是她決定將你帶進她的房間……",
  str_files_story_des_21504 = "渡收到了你送的禮物，這似乎勾起了他曾身為醫生的回憶。",
  str_files_story_des_21600 = "能讓人看到心中思念之事的古怪磁帶，泰莎、沙利葉、艾蕾雅會如何面對它呢？",
  str_files_story_des_21601 = "泰莎收到了你送的光能哨糖，卻被激起了一段不安的回憶……",
  str_files_story_des_21603 = "艾蕾雅希望買一件嶄新的裙子，卻因為種種原因無法如願。原來這個女孩身上背負著比想像中更沉重的「詛咒」……",
  str_files_story_des_21604 = "似乎有要事詳談的沙利葉，為了探尋自己祖父的「死亡之謎」煞費苦心。可是身為白夜城天使的加百列和這一切又有什麼關係呢……？",
  str_files_story_des_21700 = "三個故事三個人，三個故事一個人，到底是一個還是三個，還是……？",
  str_files_story_des_21701 = "希卡蕾講述了一個奇怪的故事給你聽，但不管是這個故事，還是希卡蕾自己對故事的態度，都讓你覺得意味深長……",
  str_files_story_des_21702 = "貝芙麗講述了一個關於她祖先的故事給你聽，這是個有關貴族精神的故事。但這種貴族精神在讓你敬佩的同時，又覺得有些彆扭……",
  str_files_story_des_21703 = "康斯坦丁講述了一個北境狩獵暗鬼的故事給你聽。但這次狩獵聽起來，每個地方都充滿著詭異的氛圍……",
  str_files_story_des_21800 = "醒山突然邀請你參加紅油扳手舉辦的慶典，並暗示你幫忙照顧多恩。只有走進這個慶典才會發現，原來這一切是為了歡迎你們的到來而準備。",
  str_files_story_des_21801 = "伊芙為什麼深夜在尋找「火藥」與「硫磺」之類的東西，她到底在做什麼……",
  str_files_story_des_21802 = "身為紅油扳手老大的醒山突然提出了一個問題——最代表紅油扳手的東西是什麼？討論過後你才發現，原來醒山提問的原因是他想要為某人準備禮物……",
  str_files_story_des_21803 = "多恩最近似乎因為什麼而煩惱的樣子，去幫幫她吧……",
  str_files_story_des_21900 = "祕月之約已至，親愛的「無名氏」，去選一本好書，與我們月下共讀吧。",
  str_files_story_des_21901 = "夢魘始終縈繞在拜里厄心頭，只有雙手拂過書本的時候，她才能感受到片刻的安寧……",
  str_files_story_des_21902 = "酒杯中的人看著你的眼睛，你卻只能看見那求而不得之人。",
  str_files_story_des_21903 = "今晚八點三十分在拉德·楊音樂廳，你將見證世界上最詭祕、美麗、偉大的交響詩篇！",
  str_files_story_des_23001 = "你無意中撞見了剛打完架回來的烈雀，你擔心她受了傷，卻反被她傳授了一些打架的專業知識。但知更問起的時候，烈雀卻驚慌失措，原來她受傷的原因正是因為知更……",
  str_files_story_des_23101 = "站在兩公尺外的距離，你試圖幫助知更挑選適合送給烈雀的禮物。但知更送禮物的眼光，怎麼看都覺得十分詭異……",
  str_files_story_des_23201 = "你最近總被蜜雅的另一個人格「芭芭雅嘎」欺負，於是你只好去詢問蜜雅。最後發現，芭芭雅嘎欺負你，是因為你招惹了不該惹的——那個人。",
  str_files_story_des_23301 = "庫絲庫塔最近總是早出晚歸，出於關心，你詢問庫絲庫塔是否發生了什麼事……於是，庫絲庫塔帶你來到了——「她」的墓碑面前？！",
  str_files_story_des_23401 = "瀧接受了一份奇怪的委託——尋找黃金沙蟲。你和瀧一同前往沙蟲故鄉的紅油沙漠，希望能找到這舉世無雙的特殊沙蟲，沒想到價值連城的黃金沙蟲居然被黑潮製作成了金閃閃的沙蟲蛋白粉？！",
  str_files_story_des_23501 = "因為感受到大家的喜愛而時常煩惱的弗勞爾又陷入了擔心之中，究竟要如何安慰他才好？",
  str_files_story_des_23601 = "大家對斯莫奇印像似乎很差，於是一項提升斯莫奇形象的計畫開始了……",
  str_files_story_des_23701 = "面對導航員「染上」的一些不是疾病的「病」，克用了一些不是藥的「藥」來治療，果然奏效。",
  str_files_story_des_23801 = "巨像上出現一塊寫著「挑戰巨像最強者」的神奇木牌，到底是怎麼回事呢……",
  str_files_story_des_23901 = "不小心打碎了艾爾戈絲貴重的珍品，她的反應卻出乎意料……",
  str_files_story_des_24001 = "在巨像上，你和普律瑪就一本書展開了討論，她為你講述一段聽起來熟悉又陌生的故事……",
  str_files_story_des_24101 = "納努塞爾為巨像添置了許多植物盆栽，你從中挑選一盆仙人掌放在臥室，可是幾天後卻發生了怪事……",
  str_files_story_des_24201 = "塔塔忽然問你喜歡什麼樣的女人，這孩子最近是怎麼了……",
  str_files_story_des_24301 = "你偶然間獲得一份珍的紀錄，上面寫著貝菲爾的私人興趣。而她似乎正急切地想要銷毀這個「證據」……",
  str_files_story_des_24401 = "在白火傭兵團度過了「交易日」後……好像更瞭解路克了。",
  str_files_story_des_24501 = "彼亞塔曼一反常態，忽然戴著墨鏡來找你幫忙……究竟發生了什麼事？",
  str_files_story_des_24601 = "最近光靈間流傳著一本祕密畫集，據說畫集囊括了你所有畫作，而畫集的編者是那兩位身穿西裝的……",
  str_files_story_des_24701 = "原本只是想問狡木和海蒂在討論什麼的你，莫名其妙被拉去參加一場……「金頭腦大對決」？",
  str_files_story_des_24801 = "啟光治安官柯蒂因為小意外落下許多工作，要幫她處理這些事情嗎？",
  str_files_story_des_24901 = "飢餓難耐的你發現愛洛拉烘烤的蜂蜜蛋糕，但愛洛拉卻要求你在食用之前，必須做一件事……",
  str_files_story_des_25001 = "聽說巨像來了一位神乎其技的讀心大師，他究竟是怎麼做到的？",
  str_files_story_des_25101 = "希諾普好像在隱瞞什麼，要去問清楚才行。",
  str_files_story_des_25201 = "最近艾莉法總會在巨像上聽到奇怪的聲音，到底是怎麼回事呢……",
  str_files_story_des_25301 = "露比的包包裡為什麼放著那麼多別人的東西？關於這個，露比自己也不太清楚……",
  str_files_story_des_25401 = "芙洛琳急急忙忙找到我，說有重要的事情。",
  str_files_story_des_25501 = "花芸說有事情想要拜託我幫忙，希望我快點去休息室找她。",
  str_files_story_des_25601 = "那一天，神樂鈴響起。姍姍來遲的凜音向你傳授了雲島的習俗……",
  str_files_story_des_25701 = "柏乃最近鬼鬼祟祟的，像是有什麼心事……",
  str_files_story_des_25801 = "雨森似乎正在休息室進行特訓，要不要去看一下呢？",
  str_files_story_des_25901 = "瑤向你講述了自己之前四處遊歷、行俠仗義的往事。",
  str_files_story_des_26001 = "阿桃和阿杏聯繫我，說想要討論料理相關的事情。",
  str_files_story_des_26101 = "在蜂和銀城的引薦下，一位謎之生物來到了巨像......",
  str_files_story_des_26201 = "青瞳邀請你和她一起去兜風，但車卻停在了一家正在舉辦派對的酒館外面。",
  str_files_story_des_26301 = "羅伊發佈了一份「尋求助手試驗新發明」的委託，酬勞十分可觀。",
  str_files_story_des_26401 = "蓮想要製作一個布玩偶，於是四處尋找材料......",
  str_files_story_des_26501 = "導航員在巨像裡偶遇賈爾斯，並被捲入了一段賈爾斯創作的「故事」裡。",
  str_files_story_des_26601 = "梅從終端發來一條奇怪的訊息，似乎有重要的事情要說......",
  str_files_story_des_26701 = "竟然有機會貼身體驗萊因哈特一天的行程？！然而這趟行程似乎和你想像的不太一樣......",
  str_files_story_des_26801 = "接受了新的力量後，薇絲開始害怕自己會因此失去情感，為了解決她的煩惱，你和夥伴們策劃了一場「測試」......",
  str_files_story_des_26901 = "在空谷獲得全新的力量之後......巴頓似乎有些不對勁。希望這只是你的錯覺......",
  str_files_story_des_27001 = "妮娜邀請你品嚐一種她親手製作的「美食」，並向你講述了「美食」背後的故事。",
  str_files_story_des_27101 = "早苗要去參加「女僕補習班」的結業考試，但是參加考試的條件聽起來有點可疑......",
  str_files_story_des_27201 = "卡蓮處理了一樁棘手的「走私案件」，聽她說說究竟是怎麼回事吧？",
  str_files_story_des_27301 = "琪爾認真地制定了許多計畫，其實都是為了邀請你和身穿動力裝甲的她一起去看海而已。",
  str_files_story_des_27401 = "菲雅一個人氣鼓鼓地站在走廊中間，凱羅也不知道去了哪裡。究竟發生了什麼事呢？",
  str_files_story_des_27501 = "梅爾特、薩布莉、菲爾姆三姐妹開始了一場特殊的採訪......傑諾的回答會是什麼呢？",
  str_files_story_des_27601 = "虹霞拜託你載馬戲團成員去外出表演，誰知到達目的地後虹霞卻感覺很不舒服......",
  str_files_story_des_27701 = "珀拉珂請你帶她去影鎮購物，可實際上她是在謀劃一次特別行動。",
  str_files_story_des_27801 = "卡斯特邀請你與她一起去參加一場賭局。被「幸運」所庇佑著的她，究竟會在賭場中如何展示這一點呢？真是令人好奇。",
  str_files_story_des_27901 = "應你的要求，伊倫汀帶你前往初階法官的辦公室參觀。不料，他卻睡著了，還說了些很奇怪的夢話。",
  str_files_story_des_28001 = "據說尋根之旅可以找到創作的靈感，你帶著莉莉卡回到了她闊別已久的家鄉......",
  str_files_story_des_28101 = "米洛斯邀請你前往安德森宅邸附近來參加一場宴會，安多瑪老爺將在這場宴會上宣布一個重要的消息。",
  str_files_story_des_28201 = "一心探索俠盜精神的塞提對你伸出了及時雨般的援助之手，然而塞提自己的探索之路卻並不順暢。陷入了迷茫的她究竟會如何破局呢？",
  str_files_story_des_28301 = "阿克希亞想知道「輸」是什麼樣的感覺。這種對她而言非常新鮮體驗，她最終感受到了嗎？真令人好奇。",
  str_files_story_des_28401 = "貝爾塔要代表白夜城醫學院在影鎮進行醫學演講，但這裡的居民似乎並不太歡迎她？",
  str_files_story_des_28501 = "歌爾蒂最近罕見地失眠了。在得知困擾著她的心結後，你們決定一起去解決這個問題。",
  str_files_story_des_28601 = "維克竟然收到了來自其他神奇動物專家的挑戰！但他還是一副事不關己的樣子，真的沒問題嗎……",
  str_files_story_des_28701 = "為了珀蘭蒂讓保住工作，你同意讓她再進行一次隨身訪談，但是好像她做記錄的時機都有些微妙……",
  str_files_story_des_28801 = "仲胥邀請你前去雙榭城的家中作客，你興致勃勃地準備著出發……",
  str_files_story_des_28901 = "帶著各自的目的，你和月白來到雙榭城的商業區，卻被一個「商人」給騙了……",
  str_files_story_des_29001 = "厘青被一場突如其來的醫鬧氣得半死，但他才不會輕易放棄呢。",
  str_files_story_des_29101 = "薇絲在抱怨她寄往紅油扳手的信件有去無回，找耶利亞問問情況吧……",
  str_files_story_des_29201 = "你見凱雅的郵件袋很重而自告奮勇偕同送信。未料竟遇到一個呼天搶地的收信人……",
  str_files_story_des_29301 = "蒂娜正準備給你講述她的一個夢境，不過這似乎不只是夢境那麼簡單……",
  str_files_story_des_29401 = "擁有少女心的人，多少都憧憬過英雄救美的浪漫場景。而這種幻想，對於零恩來說並不適用。",
  str_files_story_des_29501 = "你和馬太參加出獄犯人舉辦的聚會，馬太的口不擇言不僅惹怒了大家，還令你被牢籠所困……",
  str_files_story_des_29601 = "哈提在影鎮偶然遇見一對奇怪的母女，女兒雖然不會說話，但很喜歡哈提，而母親竟然直接把女兒託付給了哈提…",
  str_files_story_des_29701 = "克莉絲汀贈與你一張歌劇院的門票，於是你決定前往白夜城的歌劇院觀看演出…",
  str_files_story_des_35001 = "鶯歌邀請你去啟光戰備室參觀，似乎有什麼新事物要與你分享……",
  str_files_story_des_35002 = "由於鐵棘騎士團物資緊缺，李奧不得不率隊深入暗面冒險搜尋。在前往暗面的路上，遇到一群需要援助的難民，李奧做出了他的選擇……",
  str_files_story_des_35003 = "那天，阿納托利找到了你，讓你取回一本遺落在休息室的書。",
  str_files_story_des_35004 = "舒瓦茲眺望遠方的時候，似乎將他帶回了回憶中的某個角落……",
  str_files_story_des_35005 = "害羞也好，笨拙也罷，總會有人喜歡如此努力而真誠的你。",
  str_files_story_des_35006 = "加晴占卜出紅油沙漠有人需要幫助，不過她的占卜時靈時不靈，甚至連水晶球都經常弄丟，她真的能完成任務嗎？",
  str_files_story_des_35007 = "旅行在給人帶來新奇體驗的同時，也會讓你從陌生人身上看到熟悉的東西。",
  str_files_story_des_35008 = "螢盞替白蘭清洗工作服，卻發現裙擺上沾染的痕跡怎麼也洗不掉。那些痕跡到底是什麼呢？",
  str_files_story_des_35009 = "你偶遇了正在巨像咖啡廳裡享用料理的希南，並圍繞美食和其他話題展開了一番討論。",
  str_files_story_des_35010 = "叭噗將你約到了德諾奧峽谷，說是有「好東西」要分享給你。到底會是什麼呢？",
  str_files_story_des_35011 = "一直將笑容掛在臉上的萊蕾，最近幾日卻總是在唉聲嘆氣。她是遇到什麼煩惱了嗎？",
  str_files_story_des_35012 = "巨像的房間中，導航員看到了一張似曾相識的白紙——某些不舒服的回憶爬上了脊背，還來不及把紙翻到背面確認，主角就先環顧四周尋找那個隨時可能出現的身影。不過出乎意料的是，預想中的情景並沒有發生……",
  str_files_story_des_35013 = "在一個難得清閒的早晨，導航員收到了來自喬瑟琳的求助，消息中提到喬瑟琳為了「赴約」，需要比平時更早完成一天的準備。\n在經過一早的忙碌之後，喬瑟琳邀請你和她一同前往約定之處……",
  str_files_story_des_35014 = "求知慾旺盛的安頓正在研究螢盞，想要解開隱藏在螢盞中的祕密。",
  str_files_story_des_35015 = "札莉雅最近向薇絲學習了精確瞄準。不知道她對光能術的控制有沒有因此進步呢？",
  str_files_story_des_35016 = "對一般光靈還不夠熟悉的三十三號打算去結交新朋友，因此急需你的幫助。",
  str_files_story_des_35017 = "法夫納好像一整天都在玩遊戲，還是過去看看他吧。",
  str_files_story_des_35018 = "康娜給我看了她的繪圖日記，看得出她真的很用心呢！",
  str_files_story_des_35019 = "再次來到這個世界的朵露，正在為你製作一份特別的料理。",
  str_files_story_des_35020 = "艾爾瑪突然想在臨空者號找一份工作，這究竟是怎麼回事呢？",
  str_files_story_des_35021 = "健康作息很重要～千萬不要熬夜唷！",
  str_files_story_des_35022 = "麗蓓卡拒絕讓其他人進入她的房間。很顯然，她不想讓別人知道她房間裡的祕密……",
  str_files_story_des_35023 = "伊莎注意到麗蓓卡一直忙於診所，所以想問問你有哪些能帶麗蓓卡去旅遊放鬆的地點，但這位姐姐卻有點操心過頭了……",
  str_files_story_des_35024 = "璇極請導航員吃飯來感謝他此前的幫助，正好，關於機巧之術，導航員也有不少感興趣的話題，兩人一拍即合，開始邊吃邊聊。",
  str_files_story_des_35025 = "伊斯塔萬神祕兮兮地傳來訊息，他似乎遇上什麼不能告訴身邊人的事情。",
  str_files_story_des_35026 = "維吉爾似乎想去參加影鎮的古董市集，但他好像不太敢一個人去......",
  str_files_story_des_35027 = "很難想像，那位大名鼎鼎的浮空商會會長手裡居然也會有壞帳。",
  str_files_story_des_35028 = "為了完成劃時代的發明，阿爾戈爾想邀請你配合她做實驗……",
  str_files_story_des_35029 = "辰霓想見識艾斯特拉大陸的新鮮玩意，你便帶她來到影鎮……",
  str_files_story_des_35030 = "羅松接到他在艾斯特拉的第一件除妖委託，會碰上什麼樣的妖魔呢……",
  str_files_story_des_35031 = "危機逼近雪松林，提亞拉向PlayerName求助，兩人聯手設下一場陷阱……",
  str_files_story_des_35032 = "蕾切爾最近一直用口服營養劑代替吃飯，空裔得知後大為震驚……",
  str_files_story_des_35033 = "澤塔最近總是一副躍躍欲試的模樣，她是不是在計畫些什麼？",
  str_files_story_des_30001 = "為了拯救瀕臨破產的巨像，薇絲不得不再次探索她「最拿手的領域」——料理……味道將會怎麼樣呢？",
  str_files_story_des_30002 = "只需要你握緊她的手，她將不再畏懼未知，而會放眼見證大海的曼妙與美麗。",
  str_files_story_des_30003 = "海市蜃樓的幻影中是複雜的真心，虛構的故事中倒映著他的真實。",
  str_files_story_des_30004 = "有價的商品買不來開心和快樂，無價的禮物卻能消解所有煩惱。",
  str_files_story_des_30005 = "風聲、鳥鳴、海浪聲，那只海螺中保存著夏日海邊浪漫的聲音，還有向你表達感謝的話語。",
  str_files_story_des_30006 = "巴頓為了建設啟光的海軍隊伍，親自踏上征程……",
  str_files_story_des_30007 = "希羅娜似乎每年這個時候，都會換上特殊的服裝，去某個誰也不知道的地方待一段時間。而這次，似乎有機會一探究竟……",
  str_files_story_des_30008 = "緋凝視著一張老照片陷入沉思，上面描繪著她曾經的樣貌。要如何為她紀念這段回憶呢？",
  str_files_story_des_30009 = "薇絲好像發現了你的私人物品……那是遠方的回憶。點燃仙女棒的她，和平時會有什麼不同呢？",
  str_files_story_des_30010 = "你在影鎮的街道上遇到珍，卻忽然聽到不遠的孤兒院傳來一聲尖叫……到底發生了什麼事？",
  str_files_story_des_30011 = "菲莉詩居然生氣了！你和薇絲面面相覷。事件的罪魁禍首卻對這一切渾然不知，坐在地上舔手掌，可愛地喵喵叫。",
  str_files_story_des_30012 = "下過雨的天氣不適合鳥類起飛，然而受傷的鳥還是奮力拍打了翅膀。牠飛往的方向，或許也是泰莎心之所向……",
  str_files_story_des_30013 = "彌加德將她的一切奉獻給工作與研究，哪怕是休憩之時……",
  str_files_story_des_30014 = "契法不知道從哪弄來一套神似維多利亞的服飾，她到底要拿這套衣服做什麼呢？",
  str_files_story_des_30015 = "突然收到卡戎的「演出邀請函」！懷著難以描述的心情，你還是依約前往……",
  str_files_story_des_30016 = "離別之時，淅瀝瀝的雨依約而來、悄然而至。不知道下一個夏天，能不能再次看見這樣的景象呢？",
  str_files_story_des_30017 = "艾蕾雅獲得了一件神奇的魔法裙子，但會在午夜十二點後變成……？",
  str_files_story_des_30018 = "你在新年當天收到了一份奇怪的禮物，巨大的禮物盒時不時傳來震動和奇妙的咳嗽聲……",
  str_files_story_des_30019 = "在鏡湖邊找到了獨自離開宴會的娜席里絲。她凝望著湖面，似乎在思考什麼。",
  str_files_story_des_30020 = "維多利亞有一面奇妙的鏡子。可是當你走到鏡子前，映出的卻不是自己的身影。",
  str_files_story_des_30021 = "露易絲與諾爾帶你守在北境某個路口，只為見到傳聞中那輛不眠不休的馬車。",
  str_files_story_des_30022 = "憂愁與煩惱並非揮之不去，有時候解開煩憂只需要三杯飲品，以及一家對的咖啡廳。",
  str_files_story_des_30023 = "娜汀換上了新衣服，認真完成巨像的值班工作，但其實你更希望她能多休息。",
  str_files_story_des_30024 = "為了學習新知，你購買了一些課程，沒想到講師居然是熟悉的人——沙利葉。",
  str_files_story_des_30025 = "夕陽下的烏列爾拉著你展開一系列「文學交流」……好像更深刻地瞭解烏列爾了。",
  str_files_story_des_30026 = "明媚的陽光下，瑪姬騎著自行車飛躍晴空，用盡全身的力量，撞飛了無辜的鋸里克……",
  str_files_story_des_30027 = "伊芙不知道從哪裡弄來一套奇怪的衣服，並打算穿著這個在紅油扳手的比賽中為大家加油？",
  str_files_story_des_30028 = "卡蓮第一次露出這樣的表情，驚愕、不安、憤怒，還有一些無法自處的扭捏和可愛的害羞。",
  str_files_story_des_30029 = "雷霆忽然邀請你一起去江富城逛街，這……該不會就是傳說中的約會吧？",
  str_files_story_des_30030 = "難得的假期，塔塔邀請大家一起玩板羽球。據說輸掉的人，必須要接受某種懲罰……",
  str_files_story_des_30031 = "誰不會貪戀那一抹櫻花香氣呢？",
  str_files_story_des_30032 = "「赤浪醒之助為換妹妹伊芙餘生安康，踏上了斬殺惡人的旅途……」這就是最近火爆東方的小說嗎？",
  str_files_story_des_30033 = "你在江富城的車站偶然遇見了伊倫汀，但卻被對方像調查嫌疑人一樣盤問……",
  str_files_story_des_30034 = "錢德菈的心理診療果然很神奇……把積壓已久的情緒都發泄出來究竟是怎樣的體驗呢？",
  str_files_story_des_30035 = "貝菲爾究竟為伊斯塔萬選了一件怎樣的衣服……真期待看到他穿上的樣子啊。",
  str_files_story_des_30036 = "克娜莉答應去做賽車比賽的啦啦隊員，可是她卻怎麼都沒有辦法邁出第一步……",
  str_files_story_des_30037 = "一名兜售公仔的女孩講述了一個關於「魔龍裁判」的神奇故事……等等，故事中的裁判好像就是……？",
  str_files_story_des_30038 = "滾燙的天氣、炙熱的彎道、刺激的賽事……瀧究竟會在這場比賽裡獲得第幾名？",
  str_files_story_des_30039 = "受拉斐爾邀請，你來到一座莊園做客。不得不說，莊園迎接客人的方式還真是別出心裁呢......",
  str_files_story_des_30040 = "她的心臟未曾如此刻這般劇烈跳動。",
  str_files_story_des_30041 = "露易絲邀請你和她一起玩「扮家家酒」的遊戲，你們將分別扮演什麼樣的角色呢？",
  str_files_story_des_30042 = "愛麗絲的糕點竟然被人偷吃了？生氣的愛麗絲決定親自懲罰偷吃賊！",
  str_files_story_des_30043 = "弗勞爾想找一個能做麵包的地方......奇怪，難道弗勞爾想轉行？",
  str_files_story_des_30044 = "黑潮為了尋找「某個東西」而特意換上了新衣服，據說這套衣服能夠幫助黑潮行動更加迅速。",
  str_files_story_des_30045 = "你和莉奧娜一起來到海邊玩耍，但沒想到......你們遇到了她最不想見到的「那個人」。",
  str_files_story_des_30046 = "斯莫奇化作黑夜裡的神奇怪盜，偷走了那枚無法估價的寶石......然而失竊的似乎遠遠不止那一枚寶石？",
  str_files_story_des_30047 = "貢露開發了一款新遊戲，如果你不能過關，就要償還巨額的巨像維修費......",
  str_files_story_des_30048 = "被放飛的雨空蝶化為空中轉瞬即逝的幻影，但路克有辦法能讓這美麗的景象永遠留存。",
  str_files_story_des_30049 = "當貝芙麗換上她的新裝束伴隨著海浪出現在沙灘上，一段傳說拉開了帷幕。",
  str_files_story_des_30050 = "想要幫助白蘭女士的你，成為了她的臨時經紀人。但是這份工作似乎並不輕鬆呢。",
  str_files_story_des_30051 = "接到委託任務的你去某地送上一百箱酒水，但你沒想到委託人竟然是......",
  str_files_story_des_30052 = "你在影鎮遇到了努力賣報的溫蒂。看來她正嘗試拓展自己的業務？",
  str_files_story_des_30053 = "希卡蕾不僅盡職盡責地守護著「墓穴」，也聆聽著所有歸屬於「墓穴」的、來自亡者的聲音。",
  str_files_story_des_30054 = "海蒂應邀來到迦南城擔任「一日治安官」的工作，然而她的工作從一開始就遇到了阻礙......",
  str_files_story_des_30055 = "為了得到傳說中的辣醬，雷文頓在影鎮監獄做起了臥底，然而事情卻和她預想中的情況背道而馳......",
  str_files_story_des_30056 = "導航員接到一份神祕的委託，前去採訪一位著名演員......",
  str_files_story_des_30057 = "黑玫瑰幫老大普律瑪讓你做她的副手，這一次她的復仇目標是個白夜城的貴族，那位審判官也追隨至此......",
  str_files_story_des_30058 = "休息日，你與伯利恆陛下一同讀書，未料卻發現一本刹雅多年前的幻想筆記……",
  str_files_story_des_30059 = "主角受邀到北境旅遊。新年前的清晨，主角睡醒之後聽到冬宮里傳來鋼琴聲，發現是諾維亞在彈琴……",
  str_files_story_des_30060 = "在迦南城流行著「正義執行AKA天罰者」的傳說——每當有人不遵守紀律，就會有一道驚雷響起……",
  str_files_story_des_30061 = "莉莉姆們雖然性格各異，但她們有著共同的「最高使命」，並願意為此付出一切。",
  str_files_story_des_30062 = "一向沉迷科研的希諾普為了躲避和貢露玩遊戲，竟然決定參加演唱會選拔賽……",
  str_files_story_des_30063 = "一年一度的冠月節又來臨了，為守護戀人們的純潔愛情，一道閃電穿梭於大街小巷之間……",
  str_files_story_des_30064 = "彼亞塔曼與你約定在白夜城城門前見面，你依約到達……",
  str_files_story_des_30065 = "克蘿伊受邀擔任貴族婚禮的表演嘉賓，怎料她的自創樂曲觸發新娘的傷心往事……大事不妙！新娘落跑了！",
  str_files_story_des_30066 = "你正在影鎮街上行走，卻忽然被陰影中躥出的陌生壯漢拐入地下沙龍中。在這裡，你遇見了傑諾……",
  str_files_story_des_30067 = "好的獵人往往善於偽裝，只有讓獵物放下戒心，才能令其無處可逃。",
  str_files_story_des_30068 = "你在影鎮街上撞見了菲雅、維克、詩燁三人，他們湊在一起，似乎在討論些什麼…",
  str_files_story_des_30069 = "你在街上看見了烈雀的身影，於是你想上前與她打招呼…",
  str_files_story_des_30070 = "佩吉和庫瑪找到你，說有個簡單的委託要你幫忙，可是你怎麼也沒想到居然會因此成為亡命之徒…",
  str_files_story_des_30071 = "旅途中你路過一個小鎮，打算在此購買補給，卻沒想到整個小鎮都向你露出獠牙。在被瘋狂鎮民追殺時，你見到了艾希……",
  str_files_story_des_30072 = "你與庫絲庫塔一同調查影鎮連環殺人案，恐怖的凶手、受驚的倖存者，危難中庫絲庫塔展現了人性的光輝……",
  str_files_story_des_30073 = "加百列要去影鎮孤兒院慰問，邀請你一路同行，於是你們共同來到了影鎮……",
  str_files_story_des_30074 = "基汀偶然得到一本黑魔法禁書，書籍的最後一頁記錄著超級恐怖的魔法煉物，基汀好不容易集齊材料，煉製開始了……",
  str_files_story_des_30075 = "為了幫莉亞的讀書會捧場，西爾瓦特地盛裝打扮了一番，沒想到卻起了反效果……",
  str_files_story_des_30076 = "雲島最近發生多起靈異事件，鬧得人心惶惶。經過凜音調查，發現罪魁禍首竟然是一隻黑貓……",
  str_files_story_des_30077 = "短小帶刺的荊棘被心存惡念之徒奉為聖物捧上神壇，那之後降下的就會是刑罰而非恩賜。",
  str_files_story_des_30078 = "芙洛琳拜託你陪她一同出海，完成異端調查團的一項祕密任務……",
  str_files_story_des_30079 = "躺在沙灘椅上，感受悠然海風——納努塞爾終於從繁忙的工作中抽身，得以在海濱之城享受片刻寧靜。",
  str_files_story_des_30080 = "米潔妮想要送一隻沙丘貓回沙漠老家，可到了紅油沙漠才發現事情並沒有那麼容易……",
